import {planRegion,validateRegionPlan,syncRegionExits,REGION_THEMES} from './region-plan.js';
import {generateRegion} from './region-generator.js';
import {readSettlementLibrary} from './settlement-library.js';
import {freshTownSeed} from './town-plan.js';
export async function regionBuilder(api){
 const library=await readSettlementLibrary(),$=s=>document.querySelector(s),esc=api.esc,target=api.project();let plan=planRegion({seed:freshTownSeed()}),selected=plan.nodes.find(n=>n.kind==='settlement').id,valid=true,controller;
 const select=(id,items,value)=>`<select id="${id}">${items.map(([v,label])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
 api.modal('Build a region',`<p><strong>Region builder · beta</strong></p><p>Plan a connected region, then build editable settlements, routes and interiors. Each outdoor map is 64 × 64 tiles. Neighbours use scrolling connections.</p><div class="field-row"><label>Seed<input id="regionSeed" type="number" min="0" max="4294967295" value="${plan.seed}"></label><label>Outdoor maps<input id="regionCells" type="number" min="6" max="20" value="9"></label><label>Settlements<input id="regionSettlements" type="number" min="2" max="6" value="3"></label></div><div class="field-row"><label>Theme${select('regionTheme',REGION_THEMES,'mixed')}</label><label>Settlement size${select('regionSize',[['village','Village'],['town','Town']],'village')}</label></div><label>Extra routes · <span id="regionLoopValue">25%</span><input id="regionLoops" type="range" min="0" max="100" value="25"></label><div class="button-row"><button id="regionPreview" type="button">Update plan</button><button id="regionReroll" type="button">New seed & layout</button></div><p id="regionPlanStatus" role="status"></p><div id="regionPlan" aria-label="Region layout"></div><fieldset><legend>Selected location</legend><label>Name<input id="regionLocationName" maxlength="60"></label><div class="field-row"><label>Type${select('regionLocationKind',[['settlement','Settlement'],['route','Route']],'settlement')}</label><label>Terrain${select('regionLocationBiome',[['meadow','Meadow'],['forest','Forest']],'meadow')}</label></div><button id="regionApplyLocation" type="button">Update location</button><div id="regionEdgeChoices"></div></fieldset><label>Terrain source${select('regionTerrain',library.profiles.filter(p=>p.terrain).map(p=>[p.id,p.id==='other'?'Other · included art packs':p.name]),'firered')}</label><fieldset><legend>Building sources · choose one or more</legend>${library.profiles.map(p=>`<label class="check"><input type="checkbox" data-region-style="${esc(p.id)}" ${p.id==='firered'?'checked':''}> ${esc(p.id==='other'?'Other · included art packs':p.name)}</label>`).join('')}</fieldset><fieldset><legend>Facilities in each settlement</legend>${[['centre','Pokémon Centre'],['mart','Mart'],['gym','Gym']].map(([id,label])=>`<label class="check"><input type="checkbox" data-region-facility="${id}" ${id!=='gym'?'checked':''}> ${label}</label>`).join('')}</fieldset><fieldset><legend>Landscape features</legend><label class="check"><input id="regionWater" type="checkbox" checked> Streams, ponds and crossing platforms</label><label class="check"><input id="regionScenery" type="checkbox" checked> Route woodland patches and flowers</label><label class="check"><input id="regionRocks" type="checkbox" checked> Scattered boulders</label></fieldset><label class="check"><input id="regionInteriors" type="checkbox" checked> Create and connect building interiors</label><div class="button-row"><button id="regionBuild" type="button" class="primary">Build & check region</button><button id="regionCancelBuild" type="button" hidden>Cancel generation</button></div><p id="regionBuildProgress" role="status"></p><p class="hint-line">Meadow and forest geography includes clustered woodland, winding paths, streams and ponds. Water crossings use the included masonry platform tiles. Coastal and highland regions still need their region-wide terrain adapters. Encounters, story progression and native Town Map artwork need authoring afterwards. The existing town generator still offers the other biomes and city presets. Review and playtest before compiling a supported ROM.</p>`);
 let disabledState=[];const setBusy=busy=>{if(busy){disabledState=[...document.querySelectorAll('#dialogBody input,#dialogBody select,#dialogBody button')].filter(e=>e.id!=='regionCancelBuild').map(e=>[e,e.disabled]);for(const[e]of disabledState)e.disabled=true;}else{for(const[e,value]of disabledState)e.disabled=value;disabledState=[];}$('#regionCancelBuild').hidden=!busy;};
 const root=$('#regionBuild'),status=message=>{if(root.isConnected)$('#regionBuildProgress').textContent=message;},fail=e=>status(e.message),options=()=>({seed:+$('#regionSeed').value,cells:+$('#regionCells').value,settlements:+$('#regionSettlements').value,loops:+$('#regionLoops').value,theme:$('#regionTheme').value,settlementSize:$('#regionSize').value});
 function preview(){const scale=70,pad=20,w=plan.width*scale+40,h=plan.height*scale+40,node=plan.nodes.find(n=>n.id===selected)||plan.nodes[0];selected=node.id;
 $('#regionPlan').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="group" aria-label="Planned region. Select a location to edit." style="display:block;width:100%;max-height:420px;background:#e4ecd9;border-radius:12px">${plan.edges.map(e=>{const a=plan.nodes.find(n=>n.id===e.from),b=plan.nodes.find(n=>n.id===e.to);return`<path d="M ${pad+a.x*scale+26} ${pad+a.y*scale+26} L ${pad+b.x*scale+26} ${pad+b.y*scale+26}" stroke="${e.backbone?'#514b7d':'#bb793d'}" stroke-width="6" ${e.backbone?'':'stroke-dasharray="5 4"'}/>`;}).join('')}${plan.nodes.map(n=>`<g role="button" tabindex="0" data-region-node="${n.id}" aria-label="${esc(n.name)}, ${n.kind}, ${n.biome}" aria-pressed="${n.id===selected}"><rect x="${pad+n.x*scale}" y="${pad+n.y*scale}" width="52" height="52" rx="${n.kind==='settlement'?8:22}" fill="${n.biome==='forest'?'#426849':'#7b9557'}" stroke="${n.id===selected?'#f5ba54':'#fff'}" stroke-width="4"/><text x="${pad+n.x*scale+26}" y="${pad+n.y*scale+24}" text-anchor="middle" fill="white" font-size="10">${n.kind==='settlement'?'Town':'Route'}</text><text x="${pad+n.x*scale+26}" y="${pad+n.y*scale+40}" text-anchor="middle" fill="white" font-size="11">${n.id+1}</text></g>`).join('')}</svg>`;
 $('#regionPlanStatus').textContent=plan.nodes.length+' outdoor maps · '+plan.nodes.filter(n=>n.kind==='settlement').length+' settlements · '+plan.edges.length+' connections. Gold: selected. Dashed: extra routes.';$('#regionLocationName').value=node.name;$('#regionLocationKind').value=node.kind;$('#regionLocationBiome').value=node.biome;
 $('#regionEdgeChoices').innerHTML='<p>Connections from this location</p>'+plan.nodes.filter(n=>Math.abs(n.x-node.x)+Math.abs(n.y-node.y)===1).map(n=>`<label class="check"><input type="checkbox" data-region-edge="${n.id}" ${plan.edges.some(e=>e.from===node.id&&e.to===n.id||e.to===node.id&&e.from===n.id)?'checked':''}> ${esc(n.name)}</label>`).join('');
 document.querySelectorAll('[data-region-node]').forEach(el=>{const choose=()=>{selected=+el.dataset.regionNode;preview();};el.onclick=choose;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();choose();}};});
 document.querySelectorAll('[data-region-edge]').forEach(el=>el.onchange=()=>{const before=structuredClone(plan),other=plan.nodes.find(n=>n.id===+el.dataset.regionEdge);plan.edges=plan.edges.filter(e=>!(e.from===node.id&&e.to===other.id||e.to===node.id&&e.from===other.id));if(el.checked)plan.edges.push({from:node.id,to:other.id,direction:other.x>node.x?'east':other.x<node.x?'west':other.y>node.y?'south':'north',backbone:false});syncRegionExits(plan);try{validateRegionPlan(plan);status('Connection updated.');}catch(e){plan=before;fail(e);}preview();});
 }
 function replan(){try{plan=planRegion(options());valid=true;selected=plan.nodes.find(n=>n.kind==='settlement').id;preview();status('Plan updated. Build when you are happy with it.');}catch(e){valid=false;fail(e);}}
 $('#regionLoops').oninput=()=>{$('#regionLoopValue').textContent=$('#regionLoops').value+'%';};for(const id of ['regionSeed','regionCells','regionSettlements','regionLoops','regionTheme','regionSize'])$('#'+id).onchange=replan;$('#regionPreview').onclick=replan;$('#regionReroll').onclick=()=>{$('#regionSeed').value=freshTownSeed();replan();};
 $('#regionApplyLocation').onclick=()=>{const n=plan.nodes.find(n=>n.id===selected),before={...n};n.name=$('#regionLocationName').value.trim()||n.name;n.kind=$('#regionLocationKind').value;n.biome=$('#regionLocationBiome').value;try{validateRegionPlan(plan);plan.settlements=plan.nodes.filter(n=>n.kind==='settlement').length;$('#regionSettlements').value=plan.settlements;preview();status('Location updated.');}catch(e){Object.assign(n,before);fail(e);}};$('#regionCancelBuild').onclick=()=>controller?.abort();
 root.onclick=async()=>{if(root.disabled)return;const session=api.session(),snapshot=structuredClone(plan),styles=[...document.querySelectorAll('[data-region-style]:checked')].map(e=>e.dataset.regionStyle),facilities=[...document.querySelectorAll('[data-region-facility]:checked')].map(e=>e.dataset.regionFacility),features={water:$('#regionWater').checked,scenery:$('#regionScenery').checked,rocks:$('#regionRocks').checked},interiors=$('#regionInteriors').checked,terrainStyle=$('#regionTerrain').value;controller=new AbortController();
 try{if(!valid)throw Error('Fix the plan settings before building.');validateRegionPlan(snapshot);if(api.project()!==target)throw Error('The project changed. Reopen the region builder.');setBusy(true);
 const result=await generateRegion(target,session?.reader,session?.id,{plan:snapshot,styles,terrainStyle,facilities,interiors,features,signal:controller.signal,progress:message=>{if(!root.isConnected)controller.abort();else status(message);}});if(controller.signal.aborted||!root.isConnected||api.project()!==target||api.session()!==session)return;
 setBusy(false);api.modal('Region review',`<p><b>${result.report.outdoorMaps} outdoor maps · ${result.report.settlements} settlements · ${result.report.interiors} interiors</b></p><p>${result.report.scrollingConnections} scrolling connections · ${result.report.waterways} waterways · ${result.report.bridgeCells} crossing tiles. All generated exits and building entrances passed the walking checks. Complete-object checks passed.</p><p>Seed ${snapshot.seed}. Existing maps stay in the project. Adding this region is one undoable edit.</p>${result.findings.length?'<h3>Review notes</h3><ul>'+result.findings.slice(0,30).map(f=>'<li>'+esc(f.mapName+': '+f.message)+'</li>').join('')+'</ul>':'<p>No structural warnings were found.</p>'}<p>Link an existing map to an unused region edge to enter it from your game. Encounters, quests, story gates and Town Map artwork still need authoring. Compile & review checks the ROM’s graphics and map capacity.</p>`,()=>{if(api.project()!==target||api.session()!==session)throw Error('The project or ROM changed. Build again before adding.');if(target.maps.some(m=>m.id===result.maps[0].id))throw Error('This region is already in the project.');if(target.maps.length+result.maps.length>80||target.assets.length+result.assets.filter(a=>!target.assets.some(b=>b.id===a.id)).length>512)throw Error('The project no longer has enough capacity. Build a smaller region.');api.change(()=>{target.maps.push(...result.maps);target.assets.push(...result.assets.filter(a=>!target.assets.some(b=>b.id===a.id)));target.links.push(...result.links);target.romObjects??=[];for(const t of result.templates)if(!target.romObjects.some(q=>q.id===t.id))target.romObjects.push(t);});api.close();api.openMap(result.startMapId);api.refresh();api.toast('Region added. Review the maps and playtest the scrolling exits.');return false;},'Add region');
 }catch(e){if(root.isConnected)fail(e);}finally{if(root.isConnected){setBusy(false);}}};preview();
}
